using System;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace TriReviewBridge {
 public partial class WorkbenchApp {
  Window HybridHistoryWindow;Func<Task> HybridHistoryLoadMore;int HybridHistoryCount;
  void RefreshHybridHistoryControl(){if(!HybridMode)return;var page=Json.Get(State,"messagePage");C<Button>("HybridEarlierHistoryButton").IsEnabled=UxScopeMatches()&&Json.Bool(page,"hasMore")&&!String.IsNullOrEmpty(Json.Str(page,"nextCursor"));C<Button>("HybridEarlierHistoryButton").ToolTip="按后台游标读取当前会话更早消息；不改变主输入、接收方或当前任务。";}
  async Task OpenHybridEarlierHistory(){if(!HybridMode||!UxScopeMatches())throw new InvalidOperationException("先选择已加载的会话。");var page=Json.Get(State,"messagePage");string cursor=Json.Str(page,"nextCursor");if(!Json.Bool(page,"hasMore")||String.IsNullOrEmpty(cursor))throw new InvalidOperationException("当前后台没有报告更早历史。");var scope=new Scope(){ProjectId=CurrentScope.ProjectId,WorkspaceId=CurrentScope.WorkspaceId,ProjectName=CurrentScope.ProjectName,WorkspaceName=CurrentScope.WorkspaceName};var dialog=Dialog("更早历史 · 只读",900,680);var panel=new DockPanel(){Margin=new Thickness(18)};var info=new TextBlock(){Text=scope.ProjectName+" / "+scope.WorkspaceName+"\n更早消息只读；主输入与接收方保持。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,12)};DockPanel.SetDock(info,Dock.Top);panel.Children.Add(info);var more=new Button(){Content="加载更早 100 条",Margin=new Thickness(0,10,0,0)};DockPanel.SetDock(more,Dock.Bottom);panel.Children.Add(more);var list=new ListBox(){HorizontalContentAlignment=HorizontalAlignment.Stretch};ScrollViewer.SetHorizontalScrollBarVisibility(list,ScrollBarVisibility.Disabled);panel.Children.Add(list);dialog.Content=panel;bool busy=false;var seen=new HashSet<string>();HybridHistoryCount=0;Func<Task> load=null;load=async()=>{if(busy||String.IsNullOrEmpty(cursor))return;busy=true;more.IsEnabled=false;try{var data=await Client.Call("/api/workspaces/"+scope.WorkspaceId+"/messages?projectId="+Uri.EscapeDataString(scope.ProjectId)+"&before="+Uri.EscapeDataString(cursor)+"&limit=100");var returnedScope=Json.Get(data,"scope");if(Json.Str(returnedScope,"projectId")!=scope.ProjectId||Json.Str(returnedScope,"workspaceId")!=scope.WorkspaceId)throw new InvalidOperationException("历史响应作用域不匹配，未展示该页。");foreach(var message in Json.Arr(Json.Get(data,"messages")).Reverse()){if(!seen.Add(Json.Str(message,"id")))continue;var body=new StackPanel(){Margin=new Thickness(9)};body.Children.Add(new TextBlock(){Text=Name(Json.Str(message,"author"))+" · "+LocalTime(Json.Str(message,"created_at")),FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,6),TextWrapping=TextWrapping.Wrap});body.Children.Add(new TextBox(){Text=Json.Str(message,"body"),IsReadOnly=true,TextWrapping=TextWrapping.Wrap,AcceptsReturn=true,MaxHeight=320,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});list.Items.Insert(0,body);}HybridHistoryCount=seen.Count;cursor=Json.Bool(data,"hasMore")?Json.Str(data,"nextCursor"):"";info.Text=scope.ProjectName+" / "+scope.WorkspaceName+"\n已读取 "+seen.Count+" 条更早消息；"+(String.IsNullOrEmpty(cursor)?"已到本次可用历史起点。":"可继续加载。")+" 主输入与接收方保持。";}catch(Exception error){info.Text="历史读取未完成："+error.Message+"。可重试；主输入与接收方保持。";}finally{busy=false;more.IsEnabled=!String.IsNullOrEmpty(cursor);}};more.Click+=async(s,e)=>await load();HybridHistoryWindow=dialog;HybridHistoryLoadMore=load;dialog.Closed+=(s,e)=>{if(HybridHistoryWindow==dialog){HybridHistoryWindow=null;HybridHistoryLoadMore=null;}};await load();dialog.Show();}
 }
}
